package ops

import (
	"testing"

	"github.com/roberson-io/cchef/internal/core"
)

// Cases transcribed from CyberChef tests/operations/tests/JA4.mjs (JA4 client).
func TestJA4Fingerprint(t *testing.T) {
	runCases(t, []opCase{
		{
			"TLS 1.3", "", "t13d1516h2_8daaf6152771_e5627efa2ab1",
			core.Recipe{{Op: "JA4 Fingerprint", Args: []any{"Hex", "JA4"}}},
		},
		{
			"TLS 1.3 Original Rendering", "", "t13d1516h2_acb858a92679_5276cb03a33b",
			core.Recipe{{Op: "JA4 Fingerprint", Args: []any{"Hex", "JA4 Original Rendering"}}},
		},
		{
			"TLS 1.3 whitespace-only ALPN", "", "t13d181220_85036bcba153_d41ae481755e",
			core.Recipe{{Op: "JA4 Fingerprint", Args: []any{"Hex", "JA4"}}},
		},
		{
			"TLS 1.3 ALPN with whitespace", "", "t13d181260_85036bcba153_d41ae481755e",
			core.Recipe{{Op: "JA4 Fingerprint", Args: []any{"Hex", "JA4"}}},
		},
		{
			"TLS 1.2", "", "t13d1715h2_5b57614c22b0_3d5424432f57",
			core.Recipe{{Op: "JA4 Fingerprint", Args: []any{"Hex", "JA4"}}},
		},
		{
			"TLS 1.2 Original Rendering", "", "t13d1715h2_5b234860e130_014157ec0da2",
			core.Recipe{{Op: "JA4 Fingerprint", Args: []any{"Hex", "JA4 Original Rendering"}}},
		},
	})
}
